          title: 'Text Blocks',
          code: 'public class Main {\n    public static void main(String[] args) {\n        String json = """\n                {\n                    "name": "Ahmed",\n                    "age": 25,\n                    "city": "Lahore"\n                }\n                """;\n        System.out.println(json);\n\n        // Using formatted()\n        String html = """\n                <html>\n                    <body>\n                        <p>Hello, %s!</p>\n                    </body>\n                </html>\n                """.formatted("World");\n        System.out.println(html);\n    }\n}',
          language: 'java',
          output: '{\n    "name": "Ahmed",\n    "age": 25,\n    "city": "Lahore"\n}',
