          id: 'ce-09-09-2',
          title: 'Optional in Practice',
          code: 'import java.util.Optional;\n\npublic class Main {\n    public static String findCity(String name) {\n        // Simulating a database lookup that might return null\n        if ("Ahmed".equals(name)) return "Lahore";\n        return null;\n    }\n\n    public static void main(String[] args) {\n        // BAD: potential NullPointerException\n        // String city = findCity("Ali").toUpperCase(); // NPE!\n\n        // GOOD: using Optional\n        Optional<String> city = Optional.ofNullable(findCity("Ahmed"));\n        System.out.println(city.orElse("Unknown")); // Lahore\n\n        Optional<String> missing = Optional.ofNullable(findCity("Ali"));\n        System.out.println(missing.orElse("Unknown")); // Unknown\n\n        // Optional with map\n        Optional<Integer> length = Optional.ofNullable(findCity("Ahmed"))\n            .map(String::length);\n        System.out.println(length.orElse(0)); // 6\n    }\n}',
          language: 'java',
